// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeLmdbQuerySource;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * An open exact prefix-run cursor reads one pinned snapshot; it must not hold the store's transaction barrier for its
 * whole lifetime, because every commit takes that barrier exclusively.
 */
class LmdbExactPrefixRunCursorConcurrencyTest {

	@TempDir
	Path directory;

	@Test
	void openExactPrefixCursorDoesNotStallConcurrentCommits() throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < 64; index++) {
					connection.add(values.createIRI("urn:cursor-commit:s:" + index),
							values.createIRI("urn:cursor-commit:p:" + (index % 4)), values.createLiteral(index));
				}
				connection.commit();
			}
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				LmdbPrefixRunPlan plan = source.prefixRunPlan(new int[] { TripleIndex.PRED_IDX }, -1, -1, -1, -1);
				LmdbPrefixRunPlan.resetMetrics();
				try (LmdbPrefixRunCursor runs = source.prefixRuns(plan, -1, -1, -1, -1, true)) {
					assertThat(runs.next()).isTrue();
					assertThat(LmdbPrefixRunPlan.OPENED.get())
							.as("the fixture must exercise the exact index cursor")
							.isPositive();
					long snapshotRows = runs.runRowCount();

					CompletableFuture<Void> commit = CompletableFuture.runAsync(() -> {
						try (var connection = repository.getConnection()) {
							connection.begin();
							connection.add(values.createIRI("urn:cursor-commit:late"),
									values.createIRI("urn:cursor-commit:p:0"), values.createLiteral("late"));
							connection.commit();
						}
					});
					commit.get(10, TimeUnit.SECONDS);

					long counted = snapshotRows;
					while (runs.next()) {
						counted += runs.runRowCount();
					}
					assertThat(counted).as("the cursor keeps reading its own snapshot").isEqualTo(64L);
				}
			}
		} finally {
			repository.shutDown();
		}
	}
}
